"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6712],{33868:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WorkbenchGuiController","desc":"Drives the Studio-authored `WorkbenchGui`. Opens via a placed Workbench\\nstation\'s `CraftPromptPart` ProximityPrompt (CollectionService tag `Workbench`,\\nshared with the Shredder on the same station Model), builds the\\nrecipe grid from `WorkbenchConfig`, fills the detail pane on selection, sends\\n`ReqCraft` on Accept, and wires Stash/Move via `PlaceableActions`. Greys\\nrecipes the player can\'t afford or that are gated by a locked Tech node;\\nrepaints live on MaterialPool and Tech-unlock changes. The recipe grid is\\nfiltered by category; the `DropdownButton` (driven by the reusable\\n`SharedModules/Gui/Dropdown` widget) selects the category and fires\\n`Signals.RequestWorkbenchCategory`. The `CloseButton` calls `close()`.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/WorkbenchGuiController.client.luau"}}')}}]);